  "dxs.bandsTip": "De kolommen van de kaart. Minstens één is nodig. U omvat de banden korter dan 4 meter.",
  "dxs.bg": "Achtergrond",
  "dxs.captions": "De onderschriften onder de labels tonen",
  "dxs.captionsTip": "De drie kleine regels (land, band en modus met de roepnaam) onder de zes labels.",
  "dxs.cellTip": "Kleur van het vakje: {kind}, in modus {mode}.",
  "dxs.cellsOf": "Vakjes {mode}",
  "dxs.colors": "Kleuren",
  "dxs.colorsHelp": "Elke modus heeft zijn eigen kleuren, zodat FT8 en FT4 aan hun bevestigingen te onderscheiden zijn. De knop ↺ gaat terug naar de fabriekskleur (die van het lichte of donkere thema).",
  "dxs.compact": "Compact formaat",
  "dxs.compactTip": "Kleinere vakjes, labels en tussenruimte, om meer plaats voor het logboek te laten. Uit: normaal formaat.",
  "dxs.factory": "Fabriekskleur",
  "dxs.guide.bands": "Banden en rijen: vink de banden en modi aan die je in de kaart wilt zien (minstens één band). “DIG” verzamelt de andere digitale modi (RTTY, PSK, JT65...). Keuzes gelden meteen en blijven na een herstart bewaard.",
  "dxs.guide.colors": "Kleuren: kies voor elke modus drie kleuren voor de vakjes (gewerkt, onbevestigd, nooit gewerkt) en voor elk label vier kleuren (achtergrond en tekst, aan en uit). De knop ↺ naast een kleur herstelt de fabriekswaarde; “Fabriekskleuren herstellen” herstelt ze allemaal. Een vakje heeft altijd een rand, ook als je een kleur gelijk aan de achtergrond kiest.",
  "dxs.guide.grid": "Het raster: één rij per modus, één kolom per band. Groen vakje = je hebt het land van het station al gewerkt op die band en in die modus; oranje = gewerkt maar niet bevestigd; leeg = nooit gewerkt. Het grote getal is het totaal van gewerkte landen.",
  "dxs.guide.labels": "De zes labels: NEW ONE = land nooit gewerkt; NEW BAND = land gewerkt, maar niet op deze band; NEW MODE = land gewerkt, maar niet in deze modus. NEW GRID, GRID BAND en GRID MODE zijn hetzelfde voor de locator (vierkant van 4 tekens). Ze gebruiken de “aan”-kleuren als ze voor het station gelden, anders blijven ze “uit”.",
  "dxs.guide.title": "Hoe het werkt",
  "dxs.guide.what": "De DXCC-kaart (onder het logboek, op de pagina Station) vertelt je, voor het station dat je oproept, of zijn land nieuw is en op welke banden en in welke modi je het al gewerkt hebt. De gegevens komen uit het logboek van Aurora en uit de externe software die in Instellingen is verbonden (bijvoorbeeld Log4OM2).",
  "dxs.ink": "Tekst",
  "dxs.intro": "Kies wat de DXCC-kaart toont en in welke kleuren. Wijzigingen gelden meteen, worden in dit programma opgeslagen en blijven na een herstart.",
  "dxs.labelTip": "{part} van het label {label}, {state}.",
