  "dxs.resetColorsTip": "Verwijdert elke gekozen kleur: de kaart gaat terug naar de kleuren van het thema. Banden, rijen en uiterlijk blijven.",
  "dxs.rows": "Te tonen rijen (modi)",
  "dxs.rowsTip": "FT8 en FT4 zijn aparte modi. DIG verzamelt de andere digitale modi (JT65, JT9, RTTY...): standaard staat het uit.",
