  "ens.apply": "Toepassen",
  "ens.audio.help": "Ingang en uitgang kies je hier en blijven na een herstart bewaard. Het ingangsniveau (opnamevolume van Windows) volgt het gekozen apparaat en wordt aangepast via de Rx-indicator.",
  "ens.discard": "Wijzigingen verwerpen",
  "ens.dxsummit.help": "De DXSummit-spot gaat nooit vanzelf weg: hij wordt verstuurd met de knop “Spot DX” in het paneel Commando’s van de pagina Station (met een DX-station gekozen), met de zenderfrequentie plus de ontvangstfrequentie en de mode als commentaar. Eén keer per station, alleen vanaf het thuisnetwerk.",
