  "not.restoreColors": "Kleuren van Aurora herstellen",
  "not.sound": "Geluid",
  "not.soundHelp": "Geluiden klinken alleen als geluidsmeldingen aan staan en na een tik op de pagina (een browserregel).",
  "not2.alertDx": "Melding bij DX-roepnaam",
  "not2.alertHelp": "Meldingen spelen het gekozen geluid af voor: een oproep aan mij, de gekozen DX-roepnaam, een nieuwe CQ-/ITU-zone, land, locator of prefix (en, met «per band», het nieuw-op-band/mode van die soort). «Per band» volgt de vakjes hierboven: het gaat af als het bericht dat label draagt. «Ook een geluid» is de gebruikelijke korte noot. Ze werken alleen met «Geluidsmeldingen» aan en de pagina open; ze zwijgen terwijl je zendt. De browser vraagt om een tik op de pagina voordat hij iets laat afspelen.",
