  "not2.grpMapColors": "DX-kaart",
  "not2.grpTable": "Markeringen en geluiden per soort",
  "not2.grpWorked": "Al gewerkt",
  "not2.help": "«Al gewerkt» is alleen een roepnaam die echt in je logboek staat en voor geen enkele ingeschakelde markering nieuw is: een station dat je nooit werkte, is nooit «al gewerkt», ook al is zijn land of zone dat wel. Staat er geen enkele markering aan, dan is er ook geen «al gewerkt». «Per band» en «per mode» bepalen wat als gedaan telt: alleen band = dezelfde band in elke mode, alleen mode = dezelfde mode op elke band, beide = dezelfde band en dezelfde mode (FT8 en FT4 zijn verschillende modes). Nieuwtjes worden berekend uit het logboek van Aurora, ADIF-bestanden en Log4OM2, zoals de DXCC-kaart. De markeringen gelden als je op Toepassen drukt; hoe gewerkte berichten worden getekend, geldt meteen op dit apparaat.",
