  "rep.forward": "Identiek doorsturen naar",
  "rep.help": "Elke gelogde QSO wordt opgeslagen in het logboek van Aurora en hierheen gestuurd. Aurora stuurt QSO’s al naar Log4OM2 met zijn secundaire UDP-server: voeg niet dezelfde ontvanger toe, ze zouden dubbel komen. Instellen met AURORA_EXPORT_UDP en AURORA_EXPORT_FILE.",
  "rep.id": "Anoniem ID van deze installatie",
