  "seq2.group": "Roep tussen de gedecodeerde berichten CQ of stop Tx als:",
  "seq2.haltReplyOther": "Stop Tx als de operator die je roept met iemand anders antwoordde",
  "seq2.help": "Het getal is het maximum aantal zendingen van hetzelfde bericht: de volgende begint niet en de volgorde gaat terug naar zoeken tussen de CQ’s of stopt. Het geldt niet voor gezochte stations of nieuw DXCC (die blijf je roepen). «Stop Tx…» onderbreekt wanneer de DX met iemand anders praat; uitgeschakeld stopt het alleen als hij dicht bij jouw frequentie praat. «Strikte CQ» respecteert de CQ-richting (CQ NA, CQ DX…) ook voor gezochte stations en nieuw DXCC. Wijzigingen gelden meteen, zonder herstart.",
