  "seq2.strictCq": "Strikte CQ-werking",
  "seq2.switchHelp": "AutoSeq, Enkele QSO, Tx1 overslaan en Al gewerkte beantwoorden zijn precies dezelfde schakelaars als in het QSO-paneel: hier en daar zie en wijzig je dezelfde toestand (onthouden na herstart). «Voorrang aan CQ’s» zoekt ook in de CQ’s van anderen naar stations om te roepen (AutoSeq 6 en 7); «grootste afstand» kiest het verste station als de rest gelijk is. De twee voorrangen gelden met Toepassen.",
