  "snd.help": "Elke functie heeft een eigen geluid, hier te kiezen of in de rij met berichttypen hierboven: voor elke functie een ander geluid, of «Geen». Een functie speelt alleen af als ze een geluid heeft en haar melding aanstaat («ook een geluid», «Meldingsgeluid afspelen», «geluid bij het eerste bericht»); een geluid kiezen zet de melding aan. Als twee functies tegelijk afgaan, speelt de belangrijkste af. Alle geluiden worden door het programma gegenereerd, er zijn geen bestanden. Het volume is het hoofdvolume; «niet afspelen tijdens het zenden» geldt voor alles, behalve «Mijn gezonden bericht», dat het Tx-signaal zelf is. «Verschillende geluiden toewijzen» vult de functies zonder meldingen aan te zetten.",
