  "sup.intro": "Als er iets mis is, maak het pakket klaar en stuur het naar wie je helpt: het bevat de logbestanden, de crashrapporten en de instellingen.",
  "sup.mailBody": "Hallo,\nIk schrijf over een probleem met Aurora.\n\nVersie: {version}\nRadio: {radio}\nPTT in gebruik: {ptt}\n\nIk voeg het pakket {name} bij dat je op het Bureaublad vindt.\n\nWat er gebeurt:\n",
