  "tip.rx.noise": "Of de noise blanker, ruisonderdrukking en auto notch aan staan: in FT8 kunnen ze het decoderen verstoren, beter uit.",
  "tip.rx.ritXit": "De offset van ontvangst (RIT) en zenden (XIT) in Hz: in FT8 horen ze nul te zijn.",
  "tip.rx.supply": "Tijdens zenden de spanning (VD) en stroom (ID) van de eindtrap en de spraakcompressie.",
