  "tip.rx.vfoB": "Frequentie en mode van VFO B, kleiner onder de hoofd-VFO (voor radio’s met dubbele VFO).",
  "tip.rxClear": "dubbelklik: wist de DX en de berichten (zoals Clear DX)",
  "tip.rxw.exclusive": "Aan, met het RX-venster open, verschijnen berichten aan jou en die van het QSO-station alleen in het RX-venster en niet ook in Bandactiviteit. Uit (standaard), worden ze in beide getoond.",
  "tip.rxw.toggle": "RX-venster: wie zendt waar de Rx-markering van de waterval staat (±50 Hz), berichten aan jou gericht en je eigen uitzendingen. Zet de Rx-markering op de DX om alleen zijn QSO te volgen.",
  "tip.sch.use": "Schakelt het schema aan of uit.",
