  "tip.stop": "Stopt het zenden meteen en schakelt de automatisering uit. Werkt altijd.",
  "tip.sup.email": "Het adres van wie je helpt: «Per e-mail versturen» opent een mail die al aan hem of haar is geadresseerd. Het blijft in dit programma opgeslagen.",
