  "tip.ui.soundPreview": "Luister naar dit geluid.",
  "tip.ui.soundStop": "Stopt het geluid dat wordt afgespeeld.",
  "tip.ui.wavelogRefresh": "Laadt de stationlijst opnieuw uit Wavelog.",
  "tip.ui.wfGain": "Helderheid van de waterval: hoger toont zwakke signalen beter.",
  "tip.ui.wfZero": "Bodemniveau van de waterval: verhoog het als de ruis te helder lijkt.",
  "tip.ui.wishClose": "Sluit deze melding.",
  "tip.ui.wishTune": "Stemt de radio af op de frequentie van de spot.",
  "tip.upd.enabled": "Aurora controleert zelf of er een nieuwe versie is en biedt die aan. Er wordt niets geïnstalleerd tenzij jij het vraagt.",
  "tip.upd.interval": "Hoeveel uur tussen de controles. 6-24 uur is genoeg.",
  "tip.upd.prereleases": "Versies die als “pre-release” zijn gemarkeerd (rc, beta). Normaal uitgeschakeld.",
  "tip.upd.repo": "De GitHub-repository waar de releases verschijnen, bijvoorbeeld wifi75/Aurora.",
  "tip.upd.token": "Een privé-repository kan niet zonder toestemming worden gelezen: maak op GitHub een fine-grained token met alleen leestoegang tot de releases van deze repository en vul het hier in. Het blijft in het gegevensbestand van Aurora, gaat nooit naar de pagina en mag niet in de repository worden gezet.",
  "tip.wfs.barsOn": "In de fabriek aan. Toont de twee verticale balken op de waterval (groen Rx, rood Tx), zo breed als het signaal van de mode (FT8 43,75 Hz, FT4 62,5 Hz), en de twee witte lijnen die de aanwijzer volgen. Uit, dan blijven alleen de labels over.",
  "tip.wfs.bpp": "Hoeveel spectrumkanalen (elk 0,73 Hz) worden opgeteld tot één pixel van de waterval, van 1 tot 100. Fabriekswaarde 5: één pixel is 3,7 Hz en een FT8-signaal blijft smal en leesbaar. Minder kanalen = meer detail en meer ruis; meer kanalen = gladdere waterval maar bredere signalen.",
  "tip.wfs.flatten": "In de fabriek uit. Haalt de achtergrondruiscurve over de band weg (past een polynoom aan de laagste punten van elke rij en trekt die af): handig als het filter van de radio de achtergrond scheef trekt.",
  "tip.wfs.freqOn": "In de fabriek uit. Als je de aanwijzer over de waterval beweegt, toont het de audiofrequentie op dat punt, in Hz.",
  "tip.wfs.gain": "Van -50 tot 50, fabriek 0. Vermenigvuldigt de niveaus met 10^(waarde/50): hoger zetten maakt signalen helderder (en breder), lager zetten maakt ze smaller en donkerder.",
  "tip.wfs.gain2d": "Van -50 tot 50, fabriek 0: hoeveel de curve van de grafiek stijgt per dB signaal.",
  "tip.wfs.jtdx": "Stelt een snelle waterval in: 15 rijen per seconde (~225 per FT8-periode), 5 bins per pixel, start 0 Hz, N Avg 1, palet Default, Flatten uit, versterking en nulpunt 0, huidig spectrum op 30 %, groene periodelijn.",
  "tip.wfs.navg": "Hoeveel spectrumrijen worden gemiddeld voordat er één getekend wordt, van 1 tot 50 (fabriek 1). Hoger = tragere en minder ruisige waterval. Aurora berekent 15 rijen per seconde, dus 4 of 5 hier tekent ongeveer elke 0,29 s een rij.",
  "tip.wfs.palette": "De kleuren van de waterval: 30 paletten (fabriek «Default»: zwart, blauw, geel, rood) plus een eigen palet. Zwakke niveaus staan aan het begin van de schaal, sterke aan het einde.",
  "tip.wfs.paletteEditor": "De kleurpunten van je palet: tussen het ene punt en het volgende verandert de kleur geleidelijk (2 tot 255 punten). Een kleur wijzigen activeert hem.",
  "tip.wfs.periodLine": "Een groene horizontale lijn in de waterval bij elke nieuwe periode (geel als je erin gezonden hebt): ze scheidt periodes en toont welke signalen gelijktijdig zijn. Uit, dan loopt de waterval zonder onderbrekingen door.",
  "tip.wfs.preview": "De echte waterval en het echte spectrum, getekend zoals op de Station-pagina: elke optie hieronder is meteen zichtbaar. Het voorbeeld gaat uit als je het sluit, van tabblad wisselt of het venster minimaliseert, en gebruikt dan niets.",
  "tip.wfs.scale": "In de fabriek aan. Deelt elke rij door zijn mediaanwaarde: de achtergrondruis heeft altijd dezelfde kleur, wat het audioniveau ook is, en alleen signalen erboven vallen op. Uit, dan volgen de kleuren het absolute niveau.",
  "tip.wfs.specMode": "«Huidig»: het laatste spectrum (fabriek). «Cumulatief»: het gemiddelde van de hele lopende periode, dat stabiele signalen naar voren brengt en bij elke nieuwe periode opnieuw begint.",
  "tip.wfs.specPct": "Hoeveel van de hoogte de spectrumgrafiek onder de waterval inneemt, van 0 (verborgen) tot 100 (fabriek 30). De waterval verdwijnt nooit helemaal.",
  "tip.wfs.speed": "Hoe snel de waterval scrolt. Normaal: één rij per half FT8-symbool (0,288 s) per N Avg, ~52 rijen per periode van 15 s, elk signaal is een compact blok. Sneller: 15 rijen per seconde per N Avg, ~225 rijen per periode, signalen worden lange strepen.",
  "tip.wfs.start": "Audiofrequentie van de linkerrand van de waterval, van 0 tot 4900 Hz (fabriek 0). Hoger zetten snijdt het lage deel af en vergroot de rest. Het rechteruiteinde blijft de filterbreedte van de radio.",
  "tip.wfs.wsjtx": "Zet alles terug op de fabriekswaarden van Aurora: één rij per 0,288 s (~52 rijen per FT8-periode), 4 bins per pixel, start 0 Hz, N Avg 1, palet Default, Flatten aan, versterking en nulpunt 0, cumulatief spectrum op 30 %, groene periodelijn.",
  "tip.wfs.zero": "Van -50 tot 50, fabriek 0. Verschuift de hele kleurenschaal: hoger zetten maakt ook de achtergrond helderder, lager zetten maakt de achtergrond donkerder en laat alleen sterke signalen over.",
  "tip.wfs.zero2d": "Van -50 tot 50, fabriek 0: verschuift de hele curve van de grafiek omhoog of omlaag.",
  "tip.wft.stamp": "Schrijft de tijd (UTC) en de band op de waterval aan het begin van elke periode.",
  "tip.win.shown": "Vink uit om het paneel van het stationsscherm te halen; vink opnieuw aan om het terug te brengen. “De indeling herstellen” toont ze weer allemaal.",
  "tip.wish.bands": "Bijvoorbeeld 20m en 15m, gescheiden door een komma. Leeg = alle banden.",
  "tip.wish.calls": "Bijvoorbeeld 3Y0J. Het komt ook overeen met een achtervoegsel (K1ABC/P) of een voorvoegsel (F/K1ABC).",
  "tip.wish.cooldown": "Van 1 tot 240. Een station dat elke 15 seconden CQ roept, waarschuwt je één keer en wacht dan zo lang.",
  "tip.wish.countries": "De landnaam zoals je die in de berichtenlijst ziet (Bulgaria, Fed. Rep. of Germany…).",
  "tip.wish.enabled": "Uit: de lijst blijft bestaan maar er gaat geen melding af.",
  "tip.wish.fromCluster": "Zoekt de gezochte stations ook in DX Cluster-spots (je ziet ze zelfs voordat je ze ontvangt).",
  "tip.wish.fromDecodes": "Zoekt de gezochte stations tussen de berichten die je ontvangt.",
  "tip.wish.grids": "Locatorvakken van vier tekens, bijvoorbeeld JN45.",
  "tip.wish.notifyUrl": "Optioneel. Installeer de gratis ntfy-app op je telefoon, kies een geheim topic (bijvoorbeeld aurora-jouw-naam-1234) en schrijf hier https://ntfy.sh/aurora-jouw-naam-1234. De melding komt aan, ook met gesloten pagina en van huis weg. Het bericht loopt via de ntfy-server: gebruik een moeilijk te raden topic, of je eigen ntfy-server.",
  "tip.wish.prefixes": "De roepnaam begint zo: VP8, ZL9, 3Y. Handig voor expedities.",
