  "upd.intro": "De controle leest de laatst gepubliceerde release (naam, notities en adres). Verschijnt er een nieuwe versie, dan downloadt Aurora die op de pc meteen op de achtergrond en controleert de handtekening, zonder te installeren: een kleine balk bovenaan toont de voortgang en daarna «Installeren en herstarten». Als je het ntfy-adres in het tabblad Gezocht hebt ingevuld, komt de melding ook op je telefoon.",
